function rd_comparison_catalog(){return array_filter(rd_library_content(),static fn($item,$key)=>str_starts_with($key,'compare-'),ARRAY_FILTER_USE_BOTH);}
function rd_material_catalog(){return array_filter(rd_library_content(),static fn($item,$key)=>$item['parent']==='material-library' && !str_starts_with($key,'compare-'),ARRAY_FILTER_USE_BOTH);}

function rd_solution_catalog(){return array_filter(rd_library_content(),static fn($item,$key)=>$item['parent']==='solutions'&&!str_starts_with($key,'compare-')&&!in_array($key,['contractor-selection','quotation-review'],true),ARRAY_FILTER_USE_BOTH);}
function rd_project_catalog(){return array_filter(rd_library_content(),static fn($item)=>$item['parent']==='project-guides');}
